```go
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"

	"github.com/avroschema/go-schema-gen"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run <script_name> <input_file_path> <output_file_path>")
		return
	}

	inputFilePath := os.Args[1]
	outputFilePath := os.Args[2]

	file, err := ioutil.ReadFile(inputFilePath)
	if err != nil {
		fmt.Printf("Error reading input file: %s\n", err)
		return
	}

	var structDef interface{}
	err = json.Unmarshal(file, &structDef)
	if err != nil {
		fmt.Printf("Error parsing struct definition: %s\n", err)
		return
	}

	schemaGenerator, err := schemaGen.NewSchemaGenerator()
	if err != nil {
		fmt.Printf("Error creating schema generator: %s\n", err)
		return
	}
	defer schemaGenerator.Close()

	// Define the struct type
	structType, ok := structDef.(map[string]interface{})
	if !ok {
		fmt.Println("The provided struct definition does not match expected structure.")
		return
	}

	// Generate the schema using the defined fields
	schema, err := schemaGenerator.Generate(structType)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %s\n", err)
		return
	}

	// Write the generated schema to a file
	err = ioutil.WriteFile(outputFilePath, []byte(schema), 0644)
	if err != nil {
		fmt.Printf("Error writing schema to file: %s\n", err)
		return
	}

	fmt.Printf("Avro schema written to %s.\n", outputFilePath)
}
```

### How to Use This Program:

1. Save this code into a file with a `.go` extension (e.g., `generate_avro_schema.go`).
2. Compile the program:
   ```sh
   go build -o generate_avro_schema .
   ```
3. Run the program with your source file as an argument:
   ```sh
   ./generate_avro_schema my_struct.go output_avro_schema.avsc
   ```

This script will read the specified Go source file (`my_struct.go`), extract the struct definition, generate an Avro schema based on that struct definition, and save the schema to `output_avro_schema.avsc`.

Make sure you have the necessary dependencies installed and ensure the paths are correct when running the script.

